3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Assigns the owner's numeric {@code membershipLevel} (1 to 3) at creation time.
8	 *
9	 * <p>The level starts at 1, gains 1 when the owner has an email address, and gains 1 when the
10	 * owner's {@code namesakeCount} is 0, then is capped at 3. (Level 4 is reserved for tenure.)
11	 *
12	 * <p>Runs in the {@code POST /api/owners} pipeline after {@link CountOwnerNamesakes} (so
13	 * {@code namesakeCount} is already frozen) and before {@link SaveOwner} (so the value is persisted)
14	 * and {@link AuditOwnerCreated} (so the audit line can record it). Frozen at creation and returned
15	 * unchanged on later reads.
16	 */
17	public class AssignOwnerMembershipLevel {
18	
19	    public void service(@Val Owner owner) {
20	        int level = 1;
21	        String email = owner.getEmail();
22	        if (email != null && !email.isBlank()) {
23	            level++;
24	        }
25	        Integer namesakeCount = owner.getNamesakeCount();
26	        if (namesakeCount != null && namesakeCount == 0) {
27	            level++;
28	        }
29	        owner.setMembershipLevel(Math.min(level, 3));
30	    }
31	}
