7	/**
8	 * Assigns the owner's {@code householdSize}: the number of owners sharing this owner's
9	 * {@code householdId} once this create completes.
10	 *
11	 * <p>Runs in the {@code POST /api/owners} pipeline after {@link AssignOwnerHousehold} (so the shared
12	 * {@code householdId} is already set and existing members are backfilled) and before
13	 * {@link SaveOwner} (so the new owner is not yet persisted). The count is therefore every existing
14	 * owner carrying the same id plus one for the owner being created. An owner that did not opt into a
15	 * household has no {@code householdId} and counts as a household of one. The value is frozen at
16	 * creation time.
17	 */
18	public class CountOwnerHousehold {
19	
20	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
21	        String householdId = owner.getHouseholdId();
22	        int count = 1; // the owner being created, not yet persisted
23	        if (householdId != null) {
24	            for (Owner existing : ownerRepository.findAll()) {
25	                if (householdId.equals(existing.getHouseholdId())) {
26	                    count++;
27	                }
28	            }
29	        }
30	        owner.setHouseholdSize(count);
31	    }
32	}
